-- This version is already recorded as applied in the BRAVA Store project; keep the ID in sync.
create table if not exists public.products (
  id bigint generated by default as identity primary key,
  name text not null,
  seller text not null,
  price integer not null check (price >= 0),
  category text not null check (category in ('Gorras','Accesorios')),
  color text not null default 'Arena',
  style text not null default 'Minimal',
  stock integer not null default 0 check (stock >= 0),
  badge text not null default '',
  image_url text not null default '',
  description text not null default '',
  material text not null default '',
  adjust text not null default '',
  variants text[] not null default '{}',
  rating numeric(2,1) not null default 0,
  reviews integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.products enable row level security;
grant select on public.products to anon, authenticated;
grant insert, update, delete on public.products to authenticated;
grant usage, select on sequence public.products_id_seq to authenticated;

create policy "Anyone can read active catalog" on public.products for select to anon, authenticated using (true);
create policy "Only admins can create products" on public.products for insert to authenticated with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "Only admins can edit products" on public.products for update to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy "Only admins can delete products" on public.products for delete to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');

